<?php
namespace VPM\Booking;
if(!defined('ABSPATH'))exit;
final class PartnerExperience {
    public static function profile(int $id):array{return Commerce::get($id);}
    public static function patch(int $id,array $patch):void {Tenants::authorize($id,true);DB::tx(function()use($id,$patch){global $wpdb;DB::row('partners','id',$id,true);$profile=array_merge(self::profile($id),$patch);DB::query($wpdb->prepare('INSERT INTO '.DB::table('commerce').' (partner_id,payload) VALUES (%d,%s) ON DUPLICATE KEY UPDATE payload=VALUES(payload)',$id,wp_json_encode($profile)));Operations::audit('partner.controls_saved','partner',$id);});}
    public static function controls(int $id,array $d):void {
        Config::require((Adapters::connection($id)['mode']??'')==='manual','extra_limits_manual_only');$limits=array();foreach(array('wash','charging','refuelling','custom1','custom2')as $key){$row=$d['limits'][$key]??array();$day=$row['day']??'return';Config::require(in_array($day,array('arrival','return'),true),'invalid_extra_day');$limits[$key]=array('capacity'=>!empty($row['enabled'])?Commerce::number($row['capacity']??'',1,100000):0,'day'=>$day);}
        self::patch($id,array('extra_limits'=>$limits));
    }
    public static function sales(int $id,array $d):void {
        Tenants::authorize($id,true);global $wpdb;$rate=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('rates').' WHERE partner_id=%d AND product_id=%s',$id,(string)($d['product_id']??'')),ARRAY_A);Config::require((bool)$rate,'rate_not_owned');DB::update('rates',array('enabled'=>empty($d['enabled'])?0:1),array('id'=>$rate['id']));Operations::audit('partner.sales_changed','partner',$id);
    }
    public static function readiness(int $id):array {
        Tenants::authorize($id);global $wpdb;$p=DB::row('partners','id',$id);$profile=self::profile($id);$connection=Adapters::connection($id);$rates=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.DB::table('rates').' WHERE partner_id=%d',$id),ARRAY_A);$catalogue=Products::catalogue();$own=array_filter($catalogue,fn($o)=>$o['partner_id']===$id);$prices=count(array_filter($rates,fn($r)=>(int)$r['price_cents']>=50));$capacity=count(array_filter($rates,fn($r)=>(int)$r['capacity']>0));$heights=true;foreach($own as $o)if(in_array($o['offer']['parking_type'],array('covered','garage','underground'),true)&&empty($o['offer']['max_height_cm']))$heights=false;
        $logistics=Logistics::get($id);return array(
            array('label'=>'Stammdaten und Flughafen','done'=>$p['name']!==''&&$p['airport']!=='','target'=>'overview'),
            array('label'=>'Stellplatzarten und Höhenangaben','done'=>(bool)$own&&$heights,'target'=>'products'),
            array('label'=>'Parkpreise und Bestände','done'=>$prices>0&&$capacity>0,'target'=>'inventory'),
            array('label'=>'Services und Zeiten','done'=>!empty($profile['services']),'target'=>'service-times'),
            array('label'=>'Eigenverwaltung oder Anbindung','done'=>in_array($connection['mode']??'',array('manual','external'),true),'target'=>'connections'),
            array('label'=>'Kontakt und Anfahrt','done'=>!empty($logistics['support_phone'])&&!empty($logistics['booking_email'])&&!empty($logistics['points']['handover']),'target'=>'logistics')
        );
    }
    public static function render_readiness(int $id):void {$steps=self::readiness($id);$done=count(array_filter($steps,fn($s)=>$s['done']));echo '<section class="vpm-setup"><h2>Einrichtung '.($done===count($steps)?'vollständig':'abschließen').'</h2><progress max="'.count($steps).'" value="'.$done.'"></progress><p>'.$done.' von '.count($steps).' Schritten erledigt</p><ol>';foreach($steps as $s)echo '<li><a href="#'.esc_attr($s['target']).'">'.($s['done']?'✓ ':'○ ').esc_html($s['label']).'</a></li>';echo '</ol><p>Die Vollständigkeit ersetzt keine Prüfung einer echten System- oder Zahlungsanbindung.</p></section>';}
    public static function calendar(int $id,array $d):array {
        Tenants::authorize($id);$partner=DB::row('partners','id',$id);$zone=new \DateTimeZone(Airports::get($partner['airport'])['timezone']);$input=(string)($d['from']??(new \DateTimeImmutable('today',$zone))->format('Y-m-d'));$start=\DateTimeImmutable::createFromFormat('!Y-m-d',$input,$zone);Config::require($start&&$start->format('Y-m-d')===$input,'invalid_calendar_date');$days=Commerce::number($d['days']??7,1,31);global $wpdb;$rates=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.DB::table('rates').' WHERE partner_id=%d',$id),ARRAY_A);$catalogue=Products::catalogue();$out=array();
        foreach($rates as $rate){$product=$catalogue[$rate['product_id']]??null;if(!$product)continue;$row=array('name'=>Products::label($product['offer']['product_name']),'parking_type'=>$product['offer']['parking_type'],'capacity'=>(int)$rate['capacity'],'days'=>array());for($i=0;$i<$days;$i++){$a=$start->modify('+'.$i.' days');$z=$a->modify('+1 day');$used=Adapters::usage($rate,array('departure_utc'=>$a->getTimestamp(),'return_utc'=>$z->getTimestamp()));$row['days'][]=array('date'=>$a->format('Y-m-d'),'used'=>$used['total'],'free'=>max(0,(int)$rate['capacity']-$used['total']),'percent'=>(int)$rate['capacity']?round(100*$used['total']/(int)$rate['capacity'],1):0,'charging'=>$used['charging'],'accessible'=>$used['accessible']);}$out[]=$row;}
        return array('from'=>$input,'days'=>$days,'timezone'=>$zone->getName(),'rows'=>$out);
    }
    public static function render_calendar(int $id):void {
        echo '<div class="vpm-calendar" data-api="'.esc_url(rest_url('vpm-booking/v1/portal/'.$id.'/calendar')).'" data-nonce="'.esc_attr(wp_create_nonce('wp_rest')).'"><h3>Belegung nach Stellplatzart</h3><p>Je Tag: höchste gleichzeitige Belegung und mindestens freie Plätze. Lade- und Behindertenstellplatze Plätze sind Teilbestände.</p><div class="vpm-calendar-controls"><button type="button" data-move="-1">← Zurück</button><label>Ab Datum<input type="date" class="vpm-calendar-from" value="'.esc_attr(wp_date('Y-m-d')).'"></label><label>Zeitraum<select class="vpm-calendar-days"><option value="7">Woche</option><option value="31">31 Tage</option></select></label><label>Stellplatzart<select class="vpm-calendar-type"><option value="">Alle Arten</option><option value="outdoor">Außenstellplatz</option><option value="covered">Überdacht</option><option value="garage">Parkhaus</option><option value="underground">Tiefgarage</option></select></label><button type="button" data-move="1">Weiter →</button></div><p class="vpm-calendar-status" role="status"></p><div class="vpm-calendar-result"></div></div>';
    }
    public static function messages(int $id):void {
        Tenants::authorize($id);global $wpdb;$admin=current_user_can('manage_options');echo '<section id="messages"><h2>Nachrichten</h2><p>Kunden direkt antworten. Der Versand läuft über die Plattformadresse; echte Kunden-Mailadressen bleiben verborgen.</p>';
        $rows=$wpdb->get_results($wpdb->prepare('SELECT i.*,b.public_id,b.customer_email FROM '.DB::table('inquiries').' i JOIN '.DB::table('bookings').' b ON b.id=i.booking_id WHERE b.partner_id=%d '.($admin?'':"AND i.audience='provider'").' ORDER BY i.created_at DESC LIMIT 50',$id),ARRAY_A);
        if(!$rows)echo '<p>Keine Kundenanfragen vorhanden.</p>';foreach($rows as $r){$b=DB::row('bookings','id',(int)$r['booking_id']);$customer=Experience::customer_data($b);$body=Config::open($r['payload']);echo '<article class="vpm-message-thread"><h3>'.esc_html(Experience::number($b).' · '.trim(($customer['first_name']??'').' '.($customer['last_name']??''))).'</h3><p>'.esc_html($r['state']==='completed'?'Beantwortet':'Antwort ausstehend').' · '.esc_html(wp_date('d.m.Y H:i',(int)$r['created_at'])).'</p><p class="vpm-inquiry-message">'.nl2br(esc_html($admin?$body['message']:Broker::redact($body['message'],$b['customer_email']))).'</p>';
            if(Tenants::role($id)!=='viewer'){echo '<form method="post">';wp_nonce_field('vpm_partner_portal');echo '<input type="hidden" name="partner" value="'.$id.'"><input type="hidden" name="portal_action" value="reply"><input type="hidden" name="inquiry_id" value="'.(int)$r['id'].'"><input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'"><label>Antwort an den Kunden<textarea name="body" required minlength="3" maxlength="2000" rows="4"></textarea></label><button>Nachricht senden</button></form>';}
            $sent=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.DB::table('messages').' WHERE booking_id=%d AND inquiry_id=%d ORDER BY created_at DESC LIMIT 10',$b['id'],$r['id']),ARRAY_A);foreach($sent as $m)echo '<div class="vpm-message-reply"><strong>Ihre Antwort · '.esc_html($m['state']==='queued'?'zum Versand vorgemerkt':$m['state']).'</strong><p>'.nl2br(esc_html(Config::open($m['payload'])['body'])).'</p></div>';echo '</article>';}
        echo '</section>';
    }
    public static function reply(int $id,array $d):void {Tenants::authorize($id,true);DB::tx(function()use($id,$d){$r=DB::row('inquiries','id',Commerce::number($d['inquiry_id']??'',1),true);$b=$r?DB::row('bookings','id',$r['booking_id']):array();Config::require($b&&(int)$b['partner_id']===$id&&(($r['audience']??'provider')!=='platform'||current_user_can('manage_options')),'portal_forbidden');Broker::submit($id,$b['public_id'],(string)($d['body']??''),(string)($d['request_key']??''),(int)$r['id']);DB::update('inquiries',array('state'=>'completed'),array('id'=>$r['id']));Operations::audit('partner.inquiry_answered','inquiry',(int)$r['id']);});}
    public static function render_extra_limits(int $id):void {if((Adapters::connection($id)['mode']??'')!=='manual'){echo '<section id="extra-limits"><h2>Extra-Kapazitäten</h2><p>Manuelle Tageskapazitäten werden in der Eigenverwaltung eingestellt. Bei externer Anbindung bleibt das führende System verantwortlich.</p></section>';return;}$limits=self::profile($id)['extra_limits']??array();echo '<section id="extra-limits"><h2>Optionale Tageskapazitäten für Extras</h2><p>Ohne Aktivierung keine zusätzliche Mengenbegrenzung. Bei Aktivierung gilt die Menge partnerweit über alle Stellplatzangebote, am gewählten Anreise- oder Rückreisetag.</p><form method="post">';wp_nonce_field('vpm_partner_portal');echo '<input type="hidden" name="portal_action" value="extra_limits"><input type="hidden" name="partner" value="'.$id.'">';foreach(array('wash'=>'Fahrzeugwäsche','charging'=>'Ladepaket','refuelling'=>'Betankung','custom1'=>'Eigene Leistung 1','custom2'=>'Eigene Leistung 2')as $key=>$label){$l=$limits[$key]??array();echo '<fieldset><legend>'.esc_html($label).'</legend><label><input type="checkbox" name="limits['.$key.'][enabled]" '.checked(!empty($l['capacity']),true,false).'> Tageskapazität begrenzen</label><label>Pakete/Einheiten pro Tag<input type="number" min="1" max="100000" name="limits['.$key.'][capacity]" value="'.(int)($l['capacity']??1).'"></label><label>Ausführung am<select name="limits['.$key.'][day]"><option value="arrival" '.selected($l['day']??'return','arrival',false).'>Anreisetag</option><option value="return" '.selected($l['day']??'return','return',false).'>Rückreisetag</option></select></label></fieldset>';}echo '<button>Extra-Kapazitäten speichern</button></form></section>';}
    public static function extra_available(int $partner,string $addon,array $travel):bool {
        $rule=self::profile($partner)['extra_limits'][$addon]??array();if(empty($rule['capacity']))return true;$at=$travel[($rule['day']??'return')==='arrival'?'departure_utc':'return_utc'];$date=(new \DateTimeImmutable('@'.$at))->setTimezone(new \DateTimeZone($travel['timezone']))->format('Y-m-d');global $wpdb;$used=(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(SUM(e.units),0) FROM '.DB::table('extra_allocations').' e JOIN '.DB::table('bookings').' b ON b.id=e.booking_id JOIN '.DB::table('allocations')." a ON a.booking_id=b.id WHERE e.partner_id=%d AND e.addon_id=%s AND e.service_date=%s AND b.state NOT IN ('cancelled','expired') AND (b.payment_state IN ('creating','pending','paid','partially_refunded') OR a.state='confirmed' OR a.expires_at>%d)",$partner,$addon,$date,time()));return $used<(int)$rule['capacity'];
    }
    public static function reserve_extras(array $b,array $input):void {
        if(($input['fulfilment']['mode']??'')!=='manual')return;global $wpdb;$limits=self::profile((int)$b['partner_id'])['extra_limits']??array();$travel=$input['travel']??array();if(!$travel)return;$addons=$input['offer_selection']['addons']??array();usort($addons,fn($a,$b)=>strcmp($a['id'],$b['id']));foreach($addons as $addon){$rule=$limits[$addon['id']]??array();$at=$travel[($rule['day']??'return')==='arrival'?'departure_utc':'return_utc'];$date=(new \DateTimeImmutable('@'.$at))->setTimezone(new \DateTimeZone($travel['timezone']))->format('Y-m-d');$key=$b['partner_id'].':'.$addon['id'].':'.$date;
            DB::query($wpdb->prepare('INSERT INTO '.DB::table('extra_locks').' (resource_key) VALUES (%s) ON DUPLICATE KEY UPDATE resource_key=VALUES(resource_key)',$key));$wpdb->get_var($wpdb->prepare('SELECT resource_key FROM '.DB::table('extra_locks').' WHERE resource_key=%s FOR UPDATE',$key));
            $rows=$wpdb->get_results($wpdb->prepare('SELECT e.units FROM '.DB::table('extra_allocations').' e JOIN '.DB::table('bookings').' b ON b.id=e.booking_id LEFT JOIN '.DB::table('allocations')." a ON a.booking_id=b.id WHERE e.partner_id=%d AND e.addon_id=%s AND e.service_date=%s AND b.state NOT IN ('cancelled','expired') AND (b.payment_state IN ('creating','pending','paid','partially_refunded') OR a.expires_at>%d) FOR UPDATE",$b['partner_id'],$addon['id'],$date,time()),ARRAY_A);$used=array_sum(array_column($rows,'units'));Config::require(empty($rule['capacity'])||$used+$addon['quantity']<=(int)$rule['capacity'],'extra_capacity_unavailable');
            DB::insert('extra_allocations',array('booking_id'=>$b['id'],'partner_id'=>$b['partner_id'],'addon_id'=>$addon['id'],'service_date'=>$date,'units'=>$addon['quantity']));
        }
    }
}
